import{_ as n,a0 as p,w as h,s as o,ao as d,I as l,x as i,a1 as e,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"10 个 Linux 中方便的 Bash 别名 | LCTT x X-CMD","titleTemplate":false,"description":"10 个 Linux 中方便的 Bash 别名 | LCTT (201810) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"10 个 Linux 中方便的 Bash 别名 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"10 个 Linux 中方便的 Bash 别名 | LCTT (201810) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201810/20180928 10 handy Bash aliases for Linux","title":"10 个 Linux 中方便的 Bash 别名","tag":"201810","desc":""},"relativePath":"201810/20180928 10 handy Bash aliases for Linux.md","filePath":"[post].md"}'),r={name:"201810/20180928 10 handy Bash aliases for Linux.md"};function g(u,s,k,b,c,f){const a=p("Link");return h(),o("div",null,[s[15]||(s[15]=d('<h1 id="_10-个-linux-中方便的-bash-别名" tabindex="-1">10 个 Linux 中方便的 Bash 别名 <a class="header-anchor" href="#_10-个-linux-中方便的-bash-别名" aria-label="Permalink to “10 个 Linux 中方便的 Bash 别名”">​</a></h1><blockquote><p>对 Bash 长命令使用压缩的版本来更有效率。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/bash_command_line.png?itok=k4z94W2U" alt=""></p><p>你有多少次在命令行上输入一个长命令，并希望有一种方法可以保存它以供日后使用？这就是 Bash 别名派上用场的地方。它们允许你将长而神秘的命令压缩为易于记忆和使用的东西。需要一些例子来帮助你入门吗？没问题！</p><p>要使用你创建的 Bash 别名，你需要将其添加到 <code>.bash_profile</code> 中，该文件位于你的家目录中。请注意，此文件是隐藏的，并只能从命令行访问。编辑此文件的最简单方法是使用 Vi 或 Nano 之类的东西。</p><h3 id="_10-个方便的-bash-别名" tabindex="-1">10 个方便的 Bash 别名 <a class="header-anchor" href="#_10-个方便的-bash-别名" aria-label="Permalink to “10 个方便的 Bash 别名”">​</a></h3><p>1、 你有几次遇到需要解压 .tar 文件但无法记住所需的确切参数？别名可以帮助你！只需将以下内容添加到 <code>.bash_profile</code> 中，然后使用 <code>untar FileName</code> 解压缩任何 .tar 文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias untar=&#39;tar -zxvf &#39;</span></span></code></pre></div><p>2、 想要下载的东西，但如果出现问题可以恢复吗？</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias wget=&#39;wget -c &#39;</span></span></code></pre></div><p>3、 是否需要为新的网络帐户生成随机的 20 个字符的密码？没问题。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias getpass=&quot;openssl rand -base64 20&quot;</span></span></code></pre></div><p>4、 下载文件并需要测试校验和？我们也可做到。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias sha=&#39;shasum -a 256 &#39;</span></span></code></pre></div><p>5、 普通的 <code>ping</code> 将永远持续下去。我们不希望这样。相反，让我们将其限制在五个 <code>ping</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias ping=&#39;ping -c 5&#39;</span></span></code></pre></div><p>6、 在任何你想要的文件夹中启动 Web 服务器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias www=&#39;python -m SimpleHTTPServer 8000&#39;</span></span></code></pre></div><p>7、 想知道你的网络有多快？只需下载 Speedtest-cli 并使用此别名即可。你可以使用 <code>speedtest-cli --list</code> 命令选择离你所在位置更近的服务器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias speed=&#39;speedtest-cli --server 2406 --simple&#39;</span></span></code></pre></div><p>8、 你有多少次需要知道你的外部 IP 地址，但是不知道如何获取？我也是。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias ipe=&#39;curl ipinfo.io/ip&#39;</span></span></code></pre></div><p>9、 需要知道你的本地 IP 地址？</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias ipi=&#39;ipconfig getifaddr en0&#39;</span></span></code></pre></div><p>10、 最后，让我们清空屏幕。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias c=&#39;clear&#39;</span></span></code></pre></div><p>如你所见，Bash 别名是一种在命令行上简化生活的超级简便方法。想了解更多信息？我建议你 Google 搜索“Bash 别名”或在 Github 中看下。</p><hr>',28)),l("p",null,[s[1]||(s[1]=i("via: ",-1)),e(a,{href:"https://opensource.com/article/18/9/handy-bash-aliases"},{default:t(()=>[...s[0]||(s[0]=[i("https://opensource.com/article/18/9/handy-bash-aliases",-1)])]),_:1})]),l("p",null,[s[6]||(s[6]=i("作者：",-1)),e(a,{href:"https://opensource.com/users/pmullins"},{default:t(()=>[...s[2]||(s[2]=[i("Patrick H.Mullins",-1)])]),_:1}),s[7]||(s[7]=i(" 选题：",-1)),e(a,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[3]||(s[3]=[i("lujun9972",-1)])]),_:1}),s[8]||(s[8]=i(" 译者：",-1)),e(a,{href:"https://github.com/geekpi"},{default:t(()=>[...s[4]||(s[4]=[i("geekpi",-1)])]),_:1}),s[9]||(s[9]=i(" 校对：",-1)),e(a,{href:"https://github.com/wxy"},{default:t(()=>[...s[5]||(s[5]=[i("wxy",-1)])]),_:1})]),l("p",null,[s[12]||(s[12]=i("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[10]||(s[10]=[i("LCTT",-1)])]),_:1}),s[13]||(s[13]=i(" 原创编译，",-1)),e(a,{href:"https://linux.cn/"},{default:t(()=>[...s[11]||(s[11]=[i("Linux中国",-1)])]),_:1}),s[14]||(s[14]=i(" 荣誉推出",-1))])])}const C=n(r,[["render",g]]);export{x as __pageData,C as default};
